function updateRange(id,value){let l=state.launch,c=state.capture;switch(id){case'throttle':l.throttle=+value;break;case'guidance':l.guidance=+value;break;case'roll':l.roll=+value;break;case'park-burn':state.orbit.burn=+value;break;case'park-angle':state.orbit.angle=+value;break;case'tmi-burn':state.tmi.burn=+value;break;case'tmi-angle':state.tmi.angle=+value;break;case'along':state.cruise.along=+value;break;case'lateral':state.cruise.lateral=+value;break;case'capture-burn':c.burn=+value;break;case'capture-angle':c.angle=+value;break;case'peri':c.peri=+value;break;case'trim':c.trim=+value;break;case'incl':c.incl=+value;break;}const output=$('o-'+id);if(output)output.textContent=value+(($(id)||{}).dataset?.suffix||'');save();}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled)executeAction(el.dataset.action)});
document.addEventListener('input',event=>{if(event.target.matches('input[data-range]'))updateRange(event.target.dataset.range,event.target.value)});
$('startBtn').addEventListener('click',reset);
$('continueBtn').addEventListener('click',()=>{if(!load()){reset();return;}$('introOverlay').classList.add('hide');log('Đã khôi phục nhiệm vụ được lưu trước đó.');render();});
$('restartBtn').addEventListener('click',()=>showConfirm());
$('helpBtn').addEventListener('click',()=>showHelp());
$('audioBtn').addEventListener('click',()=>{soundEnabled=!soundEnabled;$('audioBtn').textContent=soundEnabled?'♫':'♪';toast(soundEnabled?'Âm thanh được bật.':'Âm thanh đã tắt.');});
function showConfirm(){$('modal').className='modal';$('modal').innerHTML=`<div class="modal-card"><div class="modal-topline">MISSION OPERATIONS</div><h2>Bắt đầu nhiệm vụ mới?</h2><p>Tiến trình cũ sẽ bị thay thế. Bạn sẽ quay lại màn hình lắp ráp vệ tinh.</p><div class="modal-actions"><button class="btn-secondary" id="cancelRestart">HỦY</button><button class="btn-danger" id="confirmRestart">KHỞI ĐỘNG LẠI</button></div></div>`;$('cancelRestart').onclick=closeModal;$('confirmRestart').onclick=()=>{closeModal();reset()}}
function closeModal(){$('modal').className='modal hidden';$('modal').innerHTML='';}
function showHelp(){$('modal').className='modal';$('modal').innerHTML=`<div class="modal-card manual"><div class="modal-topline">MOR–28 / FIELD MANUAL</div><h2>Sổ tay điều khiển</h2><p>Đây là trò chơi <b>mission-based 2D</b>. Mỗi quyết định thay đổi điều kiện qua màn hình trạm điều khiển. Chỉ thực hiện lệnh ở thanh dưới khi hệ thống đã sẵn sàng.</p><ol><li><b>Assembly:</b> chọn một trong 3 biến thể ở mỗi 5 khe, chọn tên lửa và hoàn thành preflight.</li><li><b>Launch:</b> throttle phải cho TWR > 1; góc lái tốt là 0° so với guidance. Đạt 101 km và không vượt Max Q.</li><li><b>Separation:</b> chờ MECO rồi tách tầng 1, khởi động RL-10, tách fairing.</li><li><b>Parking & TMI:</b> dùng slider burn Δv và góc lái, so với guidance của màn hình.</li><li><b>Cruise:</b> hiệu chỉnh Δv dọc và ngang để điểm tiếp cận Mars đủ gần.</li><li><b>Mars capture:</b> phanh MOI, thực hiện aerobraking ở periapsis an toàn rồi circularization.</li><li><b>Science:</b> mở solar arrays, mở antenna, quản lý điện. Chụp và truyền tối thiểu 3 ảnh.</li></ol><p>Đường <b style="color:#cadde8">đứt mờ</b> là tuyến mục tiêu. Đường <b style="color:#7de4cf">liền xanh</b> là tuyến thực tế. Ngưỡng quỹ đạo và giá cả trong game là mô hình đơn giản hóa; không phải phương trình điều khiển nhiệm vụ MRO thực.</p><div class="modal-actions"><button class="btn-primary" id="closeHelp">ĐÃ HIỂU</button></div></div>`;$('closeHelp').onclick=closeModal;}
function showEnd(){const good=state.mission.result==='success',c=state.capture,s=state.sat;const targetNames=['Băng cực Bắc','Địa hình hành tinh','Cồn cát Martian','Vách đá cổ'];$('modal').className='modal';$('modal').innerHTML=`<div class="modal-card ${good?'success':'failure'}"><div class="modal-topline">${good?'MISSION RESULT / SUCCESS':'MISSION RESULT / FAILURE'}</div><h2>${good?'MISSION COMPLETE — MARS REACHED':'MISSION FAILED — SIGNAL LOST'}</h2><p>${good?'Vệ tinh đã vào đúng quỹ đạo mục tiêu quanh Sao Hỏa, hoàn thành quan sát và truyền ảnh về Trái Đất.':escapeHTML(state.mission.reason)}</p><div class="mission-summary"><div class="summary-cell"><small>RESULT</small><strong class="${good?'status-good':'status-bad'}">${good?'SUCCESS':'FAILED'}</strong></div><div class="summary-cell"><small>ORBIT ACCURACY</small><strong>${c.finalized?c.finalAlt.toFixed(1)+' km':'N/A'}</strong></div><div class="summary-cell"><small>IMAGES RECEIVED</small><strong>${s.returned.length}</strong></div><div class="summary-cell"><small>MISSION SCORE</small><strong>${good?state.mission.score+'/100':'—'}</strong></div></div>${good?`<div class="eyebrow">RECEIVED SURFACE IMAGES / USER-PROVIDED VISUAL REFERENCES</div><div class="gallery">${s.returned.slice(0,4).map(x=>`<figure><img src="${ASSETS['mars'+(x.region+1)]}" alt="Ảnh bề mặt Sao Hỏa vùng ${x.region+1}"><figcaption>IMAGE ${String(x.id).padStart(2,'0')} • ${targetNames[x.region]} • DOWNLINK OK</figcaption></figure>`).join('')}</div>`:`<div class="alert-card bad">Phân tích kỹ thuật: ${escapeHTML(state.mission.reason)}. Hãy điều chỉnh thiết kế hoặc các lệnh bay rồi chơi lại.</div>`}<div class="modal-actions"><button class="btn-secondary" id="reviewBtn">XEM BẢNG ĐIỀU KHIỂN</button><button class="btn-primary" id="playAgain">THỰC HIỆN NHIỆM VỤ MỚI</button></div></div>`;$('reviewBtn').onclick=closeModal;$('playAgain').onclick=()=>{closeModal();reset()};}
