function drawLaunch(){const l=state.launch;const progress=cap(l.alt/101,0,1);const earthR=Math.max(W*.56,H*.70);const ex=W*.18,ey=H+earthR*.52;planet(ex,ey,earthR,'earth');ctx.save();ctx.beginPath();ctx.rect(0,0,W,H);ctx.clip();const sx=W*.24,sy=H*.83,ex2=W*.80,ey2=H*.17;drawCurved(sx,sy,W*.35,H*.38,ex2,ey2,'#c7d9e861',2,[7,10]);const currentX=sx+(ex2-sx)*progress+Math.sin(progress*Math.PI)*l.deviation*4,currentY=sy-(sy-ey2)*progress+Math.sin(progress*Math.PI)*-H*.14;drawCurved(sx,sy,W*.35+Math.sin(l.deviation)*22,H*.39, currentX,currentY,'#80decc',2.5);dot(currentX,currentY,4,'#85ecdf');const wanted=Math.PI*.18-(1-progress)*.10,angle=.2+progress*.7+l.guidance*Math.PI/180+l.roll*Math.PI/180*.2;drawRocket(currentX,currentY,Math.min(110,H*.24),angle,l.ignited&&!l.cutoff);ctx.restore();textAt('ATMOSPHERIC ASCENT VECTOR',W*.56,H*.19,'#95b1c4',10,'left','700');textAt('ALT '+l.alt.toFixed(1)+' km',W*.71,H*.25,'#d9e7ee',16,'left','700');textAt('101 KM / MECO',W*.8,H*.12,'#d4e8f0',10,'right','700');line(W*.8,H*.14,W*.8,H*.81,'#96b1c74f',1,[4,8]);const yTop=H*.83-(H*.83-H*.17)*(l.alt/101);dot(W*.8,yTop,4,l.cutoff?'#64edcd':'#eea575');const meterX=W-21,top=H*.23,bottom=H*.79;line(meterX,top,meterX,bottom,'#6d91a38a',5);line(meterX,bottom,meterX,bottom-(bottom-top)*progress,'#84d9cb',5);textAt('ALT',meterX-3,top-9,'#afc4d1',9,'right');if(l.ignited){textAt('MAX Q '+l.maxQ.toFixed(1)+' kPa',W*.56,H*.9,l.maxQ>45?'#fa8f83':'#8bccd2',10,'left','700')}}
