function drawOverlayGuides(){ctx.strokeStyle='#8abac91a';ctx.lineWidth=1;const s=15;for(const[x,y,dx,dy]of[[14,80,1,1],[W-14,80,-1,1],[14,H-13,1,-1],[W-14,H-13,-1,-1]]){line(x,y,x+dx*s,y,'#91c7ca4a');line(x,y,x,y+dy*s,'#91c7ca4a')}textAt('MOR–28–01 / 2D SIMULATOR',W*.5,H-12,'#526d80',9,'center','500')}
function updateSim(dt){if(!state.started||state.phase!=='launch'||!state.launch.ignited||state.launch.cutoff)return;const l=state.launch;let step=dt*9.5,oldT=l.t;l.t=Math.min(260,l.t+step);const t=l.t;const guidance=Math.abs(l.guidance),roll=Math.abs(l.roll||0),thr=l.throttle/100;
 // 2D game flight path profiles, calibrated for readable HUD / gameplay; not full orbital dynamics.
 const flight=Physics.ascent(t,l.throttle,l.guidance,l.roll||0);l.alt=flight.alt;l.vel=flight.vel;l.q=flight.q;
 l.maxQ=Math.max(l.maxQ,l.q);l.deviation+=step*(guidance*.0035+(thr<.87?.012:0)+(state.slot[3]===2?.009:0)+roll*.002);if(l.q>45)l.health-=step*(l.q-45)*.12;
 if(l.health<55){fail('Max Q quá lớn: khung tên lửa vượt tải trọng khí động.');return;}if(l.deviation>18){fail('Tên lửa lệch quá xa hành lang phóng; không thể tiếp tục nhiệm vụ.');return;}
 if(l.alt>=100.8||t>=255){l.alt=101;l.cutoff=true;l.ignited=false;log('Tầng 1 MECO tại độ cao xấp xỉ 101 km.','good');toast('MECO • 101 KM / SAFE ASCENT');render();}else if(Math.floor(t/40)!==Math.floor(oldT/40))render();}
function frame(now){let dt=cap((now-lastFrame)/1000,0,.065);lastFrame=now;time+=dt;if(state.started){state.elapsed+=dt;updateSim(dt);if(typeof powerTick==='function')powerTick(dt)}resize();paintBackground();ctx.save();if(typeof shakeScene==='function')shakeScene();switch(state.phase){case'assembly':drawAssembly();break;case'launch':drawLaunch();break;case'separation':drawSeparation();break;case'parking':drawParking();break;case'tmi':drawTMI();break;case'cruise':drawCruise();break;case'capture':drawCapture();break;case'science':drawScience();break;case'end':drawEnd();break;}drawOverlayGuides();ctx.restore();if(now-lastUI>500){lastUI=now;renderTelemetry();if(state.phase==='launch'){$('topStep').textContent='MISSION CLOCK T+'+Math.floor(state.elapsed)+'s';const l=state.launch;if(l.ignited){const hint=document.querySelector('#controlPanel .hint-line');if(hint)hint.innerHTML=`ĐỘ CAO ${l.alt.toFixed(1)} km / 101 km • MAX Q ${l.maxQ.toFixed(1)} kPa • sai lệch ${l.deviation.toFixed(1)} units`}}}if(now-lastSave>1800&&state.started){lastSave=now;save()}requestAnimationFrame(frame)}
